var currentTime = msg.payload;
if (global.get("startTime") == null || global.get("startTime") == "") {
    global.set("startTime", currentTime);
}
var lastTickTime = global.get("lastTickTime") || currentTime;
var timeRemaining = global.get("timeRemaining") || 0;
var gameState = global.get("gameState");
var paused = global.get("paused") || false;

if (gameState == "STARTED" && !paused) {
    timeRemaining -= (currentTime - lastTickTime);
    global.set("timeRemaining", timeRemaining);

}

msg.timeRemaining = timeRemaining;
global.set("lastTickTime", currentTime);

node.status({fill: "green", shape:"dot", text:timeRemaining});

return msg;

var t = msg.timeRemaining;
t = t / 1000;
var h = Math.floor(t / 3600);
var m = Math.floor(t % 3600 / 60);
var s = Math.floor(t % 3600 % 60);

if (h > 0) {
    msg.formattedTimeRemaining = ("0" + h).slice(-2) + ":" + ("0" + m).slice(-2) + " h";
} else {
    if (m > 0) {
        msg.formattedTimeRemaining = m + " min";
    } else {
        msg.formattedTimeRemaining = s + " sec";
    }
}
var timePlayed = global.get("timeForRoom") - msg.timeRemaining;
if (timePlayed < 60000) {
    msg.formattedTimePlayed = Math.floor(timePlayed / 1000) + " s";    
} else {
    msg.formattedTimePlayed = Math.floor((timePlayed) / 60000) + " min";
}
msg.oxygenRemaining = Math.floor(t * 100000 / global.get("timeForRoom"));
let startTime = global.get("startTime");
msg.startTime = new Date(startTime).toLocaleTimeString();
node.status({fill: "green", shape:"dot", text:msg.startTime});
msg.ending = global.get("ending");
node.status({fill: "green", shape:"dot", text:msg.ending});
if (msg.ending == "Schwierig") {
    msg.event = "Hard ending";
} else {
    msg.event = "Easy ending";
}
return msg;

/**
 * This function gets called:
 * 1. When time has passed (every second) for which it receives:
 *  - msg.timeRemaining
 *  - msg.formattedTimeRemaining
 *  - msg.oxygenRemaining (0 - 100 - x % of 1 h)
 * 
 * 2. A message was received (ToDevice/All).
 */

let dockdoorunlocked = global.get("DockDoorUnlocked") || false;
msg.payload.dockdoorunlocked = dockdoorunlocked;
//node.status({fill: "green", shape:"dot", text:dockdoorunlocked});

if (msg.payload.event != null) {
    var pe = global.get("past_events") || "";
    pe = msg.payload.event + "\r\n" + pe;
    global.set("past_events", pe);
    //node.status({fill: "green", shape:"dot", text:msg.payload.event});

    if (msg.payload.event == "Dock door unlocked") {
        global.set("DockDoorUnlocked", true);
        msg.payload.dockdoorunlocked = global.get("DockDoorUnlocked") || false;
    }

    // Trigger difficult or easy ending if not already manually set
    if (msg.payload.event == "Cockpit door open") {
        let timeRemaining = global.get("timeRemaining");
        let ending = global.get("ending");
        if (ending == "--- (default)") {
            node.status({fill: "green", shape:"dot", text:timeRemaining});
            if (timeRemaining > 20 * 60 * 1000) {
                global.set("ending", "Schwierig");
            } else {
                global.set("ending", "Einfach");
            }
        }
    }

    if (msg.payload.event == "Power up") {
        msg.event = "power_up";
    }

    if (msg.payload.event == "Easy ending") {
        global.set("ending", "Einfach");
    }
    if (msg.payload.event == "Hard ending") {
        global.set("ending", "Schwierig");
    }

    if (msg.payload.event == "Exit door unlocked") {
        msg.event = "exit_door_unlocked";
    }

    if (msg.payload.event == "Virus upload started") {
        let timeRemaining = global.get("timeRemaining");
        timeRemaining = Math.min(timeRemaining, 15 * 60 * 1000);
        // Maximum time remaining at this point is 15 min.
        global.set("timeRemaining", timeRemaining);
        let repairSelfDestructAt = Math.max(60000, timeRemaining - 3 * 60 * 1000);
        node.status({ fill: "green", shape: "dot", text: repairSelfDestructAt });

        global.set("repair_self_destruction_at", repairSelfDestructAt);
    }

    if (msg.payload.event == "Mystery solved") {
        msg.event = "lightcontroller";
        global.set("paused", true);
        flow.set("effect", "rain");
        node.status({fill: "green", shape:"dot", text:msg.event});
    }

    if (msg.payload.event == "Self destruct") {
        msg.event = "self_destruct";        
        global.set("paused", true);
    }

    if (msg.payload.event == "AI won") {
        msg.event = "ai_won";
        global.set("paused", true);
    }
    if (msg.payload.event == "Core removed") {
        msg.event = "core_removed";
        global.set("paused", true);
    }

    return msg;
} else {
    let timeForRoom = global.get("timeForRoom");
    const MINUTES_MS = 60 * 1000;
    const INTRUDER_ALERT = timeForRoom - 5000; 
    const RIPPLIS_HINT = timeForRoom - 4 * MINUTES_MS; /* 4 min */
    const AI_WARNING = timeForRoom - 7 * MINUTES_MS; /* 7 min */
    const RIDDLE_INTERVENTION = timeForRoom - 7.7 * MINUTES_MS; /* 7 min 40 s */

    // After a few seconds, start intruder alarm
    if (msg.timeRemaining > INTRUDER_ALERT && msg.timeRemaining < INTRUDER_ALERT + 5000) {
        if (! (global.get("IntruderAlert") || false)) {
            global.set("IntruderAlert", true);
            msg.topic = "ToDevice/All";
            msg.event = "Intruder alert";
            return msg;
        }
    }

    // These events only happen if the dock door is still locked.
    if (! dockdoorunlocked) {
        // After about 4 minutes, automatically trigger Ripplis hint
        if (msg.timeRemaining > RIPPLIS_HINT && msg.timeRemaining < RIPPLIS_HINT + 2000) {
        //if (msg.timeRemaining > 3590000 && msg.timeRemaining < 3592000) {
            if (! (global.get("RipplisHint") || false)) {
                global.set("RipplisHint", true);
                node.status({ fill: "green", shape: "dot", text: "Trigger Ripplis Hint" });
                msg.topic = "ToDevice/All";
                msg.event = "Ripplis hint";
                return msg;
            }
        }

        // After 7 min, trigger AI warning
        if (msg.timeRemaining > AI_WARNING && msg.timeRemaining < AI_WARNING + 2000) {
            if (! (global.get("AIWarning") || false)) {
                global.set("AIWarning", true);
                msg.topic = "ToDevice/All";
                msg.event = "AI warning";
                return msg;
            }
        }

        // After 7 min 40, trigger help from ISS RIDDLE
        if (msg.timeRemaining > RIDDLE_INTERVENTION && msg.timeRemaining < RIDDLE_INTERVENTION + 2000) {
            if (!(global.get("ISSHelp") || false)) {
                global.set("ISSHelp", true);
                msg.topic = "ToDevice/All";
                msg.event = "ISS Riddle intervention";
                return msg;
            }
        }
    }

    // Time ran out, trigger the correct game over sequence
    if (msg.timeRemaining < 0) {
        msg.topic = "ToDevice/All";
        if (! global.get("paused")) {
            global.set("paused", true);
            if (global.get("ending") == "Schwierig") {
                msg.event = "AI won";
            } else {
                msg.event = "Out of oxygen";
            }
            return msg;
        }
    }

    // Time-based events for difficult level
    if  (global.get("ending") == "Schwierig") {
        const SELF_DESTRUCTION_ACTIVATION = global.get("repair_self_destruction_at") || 0;
        node.status({fill: "green", shape:"dot", text:SELF_DESTRUCTION_ACTIVATION});

        if (msg.timeRemaining > SELF_DESTRUCTION_ACTIVATION && msg.timeRemaining < SELF_DESTRUCTION_ACTIVATION + 2000) {
            if (!(global.get("SelfDestructionActivated") || false)) {
                global.set("SelfDestructionActivated", true);
                msg.topic = "ToDevice/All";
                msg.event = "Self destruction activated";
                return msg;
            }
        }

    }
    return null;
}

return msg;

